<?php declare(strict_types=1); namespace ProcessWire;
// Explicitly isolated real ProcessWire/MySQL acceptance. No live-site bootstrap.
$root='';foreach(array_slice($argv,1)as$arg)if(str_starts_with($arg,'--root='))$root=rtrim(substr($arg,7),'/');
if(!$root||!is_file($root.'/index.php')||trim((string)@file_get_contents(dirname($root).'/.narzan-disposable'))!=='narzan-groups-integration-v1')throw new \RuntimeException('Owned disposable group fixture required.');
require $root.'/index.php';$db=wire('database');
if(!preg_match('/^narzan_groups_[a-f0-9]{8}$/D',(string)$db->query('SELECT DATABASE()')->fetchColumn()))throw new \RuntimeException('Dedicated cloned database required.');
function check(bool $ok,string $name):void{if(!$ok)throw new \RuntimeException($name);$GLOBALS['checks']=($GLOBALS['checks']??0)+1;}
function denied(callable $operation):void{try{$operation();}catch(WireException $e){check(true,'denied');return;}throw new \RuntimeException('Expected access denial');}
$m=wire('modules')->get('Messenger');check($m instanceof Messenger,'real installed module');
check(realpath((new \ReflectionClass($m))->getFileName())===realpath($root.'/site/modules/Messenger/Messenger.module.php'),'candidate runtime belongs to clone');
$operator=wire('users')->get('roles=superuser');check($operator instanceof User&&$operator->isSuperuser(),'fixture administrator');
wire('users')->setCurrentUser($operator);$m->install();
$m->set('groups_enabled',0);check(!$m->groupsReady(),'off before explicit install');$m->installGroups($operator);check(!$m->groupsReady(),'schema does not enable feature');
$m->set('groups_enabled',1)->set('first_contact_mode','requests')->set('max_new_recipients_day',1000)->set('max_messages_minute',1000)->set('email_enabled',0);
check($m->groupsReady(),'real MySQL schema ready');$accounts=[];$suffix=bin2hex(random_bytes(4));
foreach(['a','b','c']as$l){$u=new User();$u->name='group-'.$l.'-'.$suffix;$u->email=$u->name.'@example.test';$u->pass=bin2hex(random_bytes(24));$u->save();$accounts[]=$u;}[$a,$b,$c]=$accounts;
$as=function(User $actor,callable $op){$previous=wire('user');try{wire('users')->setCurrentUser($actor);return $op();}finally{wire('users')->setCurrentUser($previous);}};
$g=$as($a,fn()=>$m->createGroup($a,'Fixture group',[(int)$b->id,(int)$c->id],'mysql_group_'.$suffix));$id=$g['id'];
check($g['type']==='group'&&count($g['members'])===1,'no forced membership');
check($as($a,fn()=>$m->createGroup($a,'Fixture group',[(int)$c->id,(int)$b->id],'mysql_group_'.$suffix))['id']===$id,'immutable creation retry');
check($as($b,fn()=>$m->conversation($id,$b))===[],'unaccepted invitation has no conversation');
check(count($as($b,fn()=>$m->groupInvitations($b)))===1,'invitation available');
$old=$as($a,fn()=>$m->sendMessage($id,$a,'Before membership','mysql_old_'.$suffix));
$as($b,fn()=>$m->respondGroupInvitation($id,$b,true));$as($c,fn()=>$m->respondGroupInvitation($id,$c,true));
check($as($b,fn()=>$m->conversationMessages($id,$b))===[],'prejoin history inaccessible');
$text=$as($b,fn()=>$m->sendMessage($id,$b,'After membership','mysql_text_'.$suffix));
$page=$as($c,fn()=>$m->conversationMessages($id,$c));check(count($page)===1&&$page[0]['sender']['id']===(int)$b->id,'third actor sees authenticated author');
$as($a,fn()=>$m->markRead($id,$a,$text['id']));$as($c,fn()=>$m->markRead($id,$c,$text['id']));
check($as($b,fn()=>$m->messageInfo($text['id'],$b))['is_read'],'group receipt covers eligible recipients');
check(!$as($a,fn()=>$m->messageInfo($old['id'],$a))['is_read'],'newcomers cannot read inaccessible old messages');
$fileInput=['filename'=>'fixture.txt','mime_type'=>'text/plain','kind'=>'file','data_base64'=>base64_encode('Private fixture bytes')];
$file=$as($a,fn()=>$m->sendAttachment($id,$a,$fileInput,'mysql_file_'.$suffix));
check($as($c,fn()=>$m->attachment($c,$file['attachment']['id']))['data_base64']===$fileInput['data_base64'],'real encrypted private attachment');
$as($b,fn()=>denied(fn()=>$m->changeGroup($id,$b,'rename',['title'=>'Denied'])));
$as($a,fn()=>$m->changeGroup($id,$a,'role',['user_id'=>(int)$b->id,'role'=>'admin']));
check($as($b,fn()=>$m->changeGroup($id,$b,'rename',['title'=>'Renamed']))['other_user']['title']==='Renamed','admin rename');
$photo=['filename'=>'fixture.png','mime_type'=>'image/png','kind'=>'file','data_base64'=>'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+jp1sAAAAASUVORK5CYII='];
$changed=$as($b,fn()=>$m->changeGroup($id,$b,'avatar',['avatar'=>$photo]));
check($changed['has_avatar']&&$changed['avatar_version']===1,'photo has independent revision');
check($as($c,fn()=>$m->groupAvatar($id,$c))['data_base64']===$photo['data_base64'],'authorized private photo');
$q=$db->prepare('SELECT title,avatar FROM messenger_groups WHERE conversation_id=?');$q->execute([$id]);$stored=$q->fetch(\PDO::FETCH_ASSOC);
check(str_starts_with($stored['title'],'menc:v1:')&&str_starts_with($stored['avatar'],'menc:v1:'),'real MySQL encrypts name and photo');
$renamed=$as($b,fn()=>$m->changeGroup($id,$b,'rename',['title'=>'Renamed again']));check($renamed['avatar_version']===1,'rename does not redownload photo');
$as($b,fn()=>denied(fn()=>$m->changeGroup($id,$b,'invite',['user_ids'=>[2147483647]])));
$as($b,fn()=>$m->changeGroup($id,$b,'remove',['user_id'=>(int)$c->id]));
$as($c,function()use($m,$id,$c,$file){denied(fn()=>$m->conversationMessages($id,$c));denied(fn()=>$m->attachment($c,$file['attachment']['id']));denied(fn()=>$m->sendMessage($id,$c,'Denied','mysql_removed_send'));});
$as($b,fn()=>$m->changeGroup($id,$b,'invite',['user_ids'=>[(int)$c->id]]));$as($c,fn()=>$m->respondGroupInvitation($id,$c,true));
check($as($c,fn()=>$m->conversationMessages($id,$c))===[],'rejoin creates a new history floor');
$as($c,fn()=>denied(fn()=>$m->attachment($c,$file['attachment']['id'])));
$as($b,fn()=>$m->changeGroup($id,$b,'avatar',['avatar'=>null]));check($as($a,fn()=>$m->groupAvatar($id,$a))===null,'photo removal explicit');
$as($a,fn()=>$m->changeGroup($id,$a,'transfer',['user_id'=>(int)$b->id]));
check($as($a,fn()=>$m->createGroup($a,'Fixture group',[(int)$b->id,(int)$c->id],'mysql_group_'.$suffix))['id']===$id,'original creator retry survives owner transfer');
$as($a,fn()=>denied(fn()=>$m->changeGroup($id,$a,'delete',[])));
$as($b,fn()=>$m->changeGroup($id,$b,'delete',[]));check($as($a,fn()=>$m->conversation($id,$a))===[],'delete denies all ordinary access');
$direct=$as($a,fn()=>$m->startConversation($a,$c,'Direct still works','mysql_direct_'.$suffix));$directId=$direct['conversation']['id'];$as($c,fn()=>$m->acceptRequest($directId,$c));
check($as($c,fn()=>$m->conversation($directId,$c))['type']==='direct','legacy direct flow remains usable');
echo json_encode(['checks'=>$GLOBALS['checks'],'database'=>'isolated MySQL clone','processwire'=>wire('config')->version,'live_site_modified'=>false],JSON_PRETTY_PRINT).PHP_EOL;
